CREATE TABLE IF NOT EXISTS admin_settings (key TEXT PRIMARY KEY,value TEXT,updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS site_visits (id SERIAL PRIMARY KEY,path TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS posts (id SERIAL PRIMARY KEY,title TEXT NOT NULL,title_en TEXT NOT NULL DEFAULT '',content TEXT,content_en TEXT,image_url TEXT,category TEXT,published INTEGER DEFAULT 1,position INTEGER DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS services (id SERIAL PRIMARY KEY,name TEXT NOT NULL,name_en TEXT NOT NULL,description TEXT,description_en TEXT,image_url TEXT,active INTEGER DEFAULT 1,position INTEGER DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS callback_slots (id SERIAL PRIMARY KEY,starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,published INTEGER DEFAULT 0,image_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),CHECK (ends_at > starts_at));
CREATE TABLE IF NOT EXISTS leads (id SERIAL PRIMARY KEY,user_id TEXT NOT NULL,request_key TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT,municipality TEXT NOT NULL,postal_code TEXT NOT NULL,pool_type TEXT,service_ids JSONB NOT NULL DEFAULT '[]',service_names JSONB NOT NULL DEFAULT '[]',slot_id INTEGER REFERENCES callback_slots(id) ON DELETE SET NULL,slot_start TIMESTAMPTZ,slot_end TIMESTAMPTZ,notes TEXT,consent INTEGER NOT NULL DEFAULT 0,consent_text TEXT,consent_at TIMESTAMPTZ,policy_version TEXT,language TEXT DEFAULT 'fr',status TEXT DEFAULT 'new',internal_notes TEXT,image_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,request_key));
CREATE TABLE IF NOT EXISTS partners (id SERIAL PRIMARY KEY,user_id TEXT NOT NULL,request_key TEXT NOT NULL,company TEXT NOT NULL,contact_name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT NOT NULL,municipalities TEXT NOT NULL,service_ids JSONB NOT NULL DEFAULT '[]',website TEXT,message TEXT,consent INTEGER NOT NULL DEFAULT 0,consent_text TEXT,consent_at TIMESTAMPTZ,language TEXT DEFAULT 'fr',status TEXT DEFAULT 'new',internal_notes TEXT,image_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,request_key));
CREATE TABLE IF NOT EXISTS uploads (id SERIAL PRIMARY KEY,user_id TEXT NOT NULL,lead_id INTEGER REFERENCES leads(id) ON DELETE SET NULL,public_id TEXT NOT NULL UNIQUE,format TEXT NOT NULL DEFAULT 'jpg',filename TEXT NOT NULL,bytes INTEGER NOT NULL DEFAULT 0,image_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS leads_user_created_idx ON leads(user_id,created_at);
CREATE INDEX IF NOT EXISTS partners_user_created_idx ON partners(user_id,created_at);
CREATE INDEX IF NOT EXISTS uploads_lead_idx ON uploads(lead_id);
CREATE INDEX IF NOT EXISTS uploads_owner_idx ON uploads(user_id);
CREATE INDEX IF NOT EXISTS callback_slots_available_idx ON callback_slots(published,starts_at,ends_at);